print(f"BioBERT KMeans clusters: {sorted(df['BB_KMeans'].unique())}")

print("\n=== STEP 2: Building Binary Document–Term Matrix ===")
count_vec = CountVectorizer(min_df=5, max_df=0.95, binary=True, stop_words='english')
bin_matrix = count_vec.fit_transform(df['Cleaned_Abstract'])
vocab      = count_vec.vocabulary_
n_docs     = bin_matrix.shape[0]
doc_freq   = np.asarray(bin_matrix.sum(axis=0)).flatten()
print(f"Binary matrix: {bin_matrix.shape} ({n_docs:,} docs × {len(vocab):,} vocab terms)")

print("\n=== STEP 3: NPMI Coherence Computation Engine ===")
EPSILON = 1e-12

def npmi_pair(idx_i, idx_j, bin_matrix, doc_freq, n_docs):
    p_i = doc_freq[idx_i] / n_docs
    p_j = doc_freq[idx_j] / n_docs
    if p_i < EPSILON or p_j < EPSILON:
        return 0.0
    col_i = bin_matrix.getcol(idx_i)
    col_j = bin_matrix.getcol(idx_j)
    joint_count = col_i.multiply(col_j).sum()
    p_ij = joint_count / n_docs
    if p_ij < EPSILON:
        return -1.0
    pmi  = np.log(p_ij / (p_i * p_j + EPSILON))
    npmi = pmi / (-np.log(p_ij + EPSILON))
    return float(np.clip(npmi, -1.0, 1.0))

def topic_coherence(topic_words, vocab, bin_matrix, doc_freq, n_docs):
    valid_words = [w for w in topic_words if w in vocab]
    if len(valid_words) < 2:
        return np.nan, []
    word_indices = [vocab[w] for w in valid_words]
    scores = []
    for idx_i, idx_j in combinations(word_indices, 2):
        scores.append(npmi_pair(idx_i, idx_j, bin_matrix, doc_freq, n_docs))
    return float(np.mean(scores)), scores

def extract_top_words_ctfidf(df, cluster_col, n_top=10, min_cluster_size=5):
    topics = {}
    for cid in sorted(df[cluster_col].unique()):
        if cid == -1:
            continue
        mask = df[cluster_col] == cid
        texts = df.loc[mask, 'Cleaned_Abstract'].values
        if len(texts) < min_cluster_size:
            continue
        vec = TfidfVectorizer(max_features=500, min_df=1, stop_words='english')
        try:
            mat = vec.fit_transform(texts)
            scores = np.asarray(mat.mean(axis=0)).flatten()
            top_idx = scores.argsort()[-n_top:][::-1]
            words = vec.get_feature_names_out()[top_idx].tolist()
            topics[cid] = words
        except ValueError:
            continue
    return topics

print("\n=== STEP 4: Computing NPMI Coherence for All 6 Configurations ===")
configs = [
    ('TF-IDF',  'KMeans',       'TF_KMeans'),
    ('TF-IDF',  'HDBSCAN',      'TF_HDBSCAN'),
    ('TF-IDF',  'Hierarchical', 'TF_Hierarchical'),
    ('BioBERT', 'KMeans',       'BB_KMeans'),
    ('BioBERT', 'HDBSCAN',      'BB_HDBSCAN'),
    ('BioBERT', 'Hierarchical', 'BB_Hierarchical'),
]

summary_rows = []
detail_rows  = []

for pipeline, method, col in configs:
    topics = extract_top_words_ctfidf(df, col, n_top=10)
    topic_npmi_list = []
    
    for cid, words in topics.items():
        score, pair_scores = topic_coherence(words, vocab, bin_matrix, doc_freq, n_docs)
        if not np.isnan(score):
            topic_npmi_list.append(score)
            detail_rows.append({
                'Pipeline':       pipeline,
                'Method':         method,
                'Cluster':        cid,
                'NPMI_Coherence': round(score, 4),
                'Top_Words':      ', '.join(words[:5])
            })
    
    mean_npmi   = float(np.mean(topic_npmi_list))   if topic_npmi_list else np.nan
    median_npmi = float(np.median(topic_npmi_list)) if topic_npmi_list else np.nan
    std_npmi    = float(np.std(topic_npmi_list))    if topic_npmi_list else np.nan
    n_topics    = len(topic_npmi_list)
    
    summary_rows.append({
        'Pipeline':       pipeline,
        'Method':         method,
        'N_Topics':       n_topics,
        'Mean_NPMI':      round(mean_npmi, 4),
        'Median_NPMI':    round(median_npmi, 4),
        'Std_NPMI':       round(std_npmi, 4)
    })
    print(f"  {pipeline:7s} + {method:12s} -> {n_topics:3d} topics | Mean NPMI = {mean_npmi:.4f} (+/- {std_npmi:.4f})")

summary_df = pd.DataFrame(summary_rows)
detail_df  = pd.DataFrame(detail_rows)

summary_df.to_csv(os.path.join(OUT_DIR, 'topic_coherence_summary.csv'), index=False)
detail_df.to_csv(os.path.join(OUT_DIR, 'topic_coherence_per_topic.csv'), index=False)

